namespace OpenTPW;

/// <summary>
/// The kart and water track slice's approximation register (docs/TRACKS.md). Each entry is tagged <c>[APPROX:TRACK-NNN]</c> at its code site (a retired one leaves its BIN labels, a reclassified one an <c>[EXT:name]</c> decision, docs/TRACKS.md); the
/// words before the colon name the topic. Everything else of the slice is traced from the Mac and Windows binaries (BIN labels at the code sites).
/// </summary>
public static class TrackApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("TRACK-001", "TRACK-HEIGHT: the vehicles sample the object under each probe in the original's modes (0x450EA0: surface records, terrain + the header's +0xA0, the instance mesh) and the terrain mode reads the original's triangle sampler 0x4527F0 at the probe; the tile instances stand on the midrange of the tile's 3 x 3 landscape vertices (0x466D70) and every mesh vertex is draped onto the landscape (0x469A80, the always-split triangles), which the face mode reads; the surface-record mode is taken for a model with a dummy record of type bit 2 (as the original: the loader's 0x44A870 sets the instance block's bit 8 that 0x450EA0 tests for exactly those, resolved), faces count from either side and are baked with the full rest transforms, the instance-mesh mode reads every 0x8000 face of the model, the Halloween and space kart stations (face-sampled station models) use the straight piece's floor, and a cell with no track gives the terrain where the original samples its owner object (or keeps the previous height without one)"),
		("TRACK-002", "TRACK-HMP: the .hmp height profile is the original's per-object height map (loader 0x451640 from the mesh loader 0x4629D0, rebuilt from the mesh by 0x451880 when missing or mis-sized); the vehicles' sampler does not read it (0x4511A0 samples faces or the terrain sampler 0x4527F0, TRACK-001) and neither do OpenTPW's vehicles; the kit parses it; the readers of the object's map (+0xCC) are the cell-height lookup 0x452AE0 (the cell owner's map byte x 100/255 plus its base height, else the landscape; callers 0x45CDC0, 0x532FC0, 0x536CA0, 0x5370E0 and the tour code 0x55ABF0, 0x55C350, 0x55CC00, TOUR-005), the instance bounding box 0x466B70 (the map's +0x1C/+0x28 extremes plus the instance height; callers 0x556AF0, 0x556B90, 0x556DE0, 0x5587F0, 0x559060, 0x5597A0, 0x55A100), the ride preview 0x4689F0 (0x486410 from 0x4AB1B0) and the cell-flag copy of the mesh creation 0x463060 (bit 0x80 cells of the map written into the landscape cells; every shipped map's flags are zero), none of which belongs to the kart or water vehicles; what those readers decide in OpenTPW's tour, ghost and bounding-box code is not traced"),
		("TRACK-004", "TRACK-X2LINK: the flow links of water crossings and tees are written as the original's line op does (0x539670: a tile with more than two arms ORs the line's direction into +0xD, so crossings get 0x14, 0x41, 0x50 or 0x05; the circuit walk 0x52A970 writes +0xD only at corners); not modelled: the clear op (ClearCell 0x53B280 -> 0x5227F0, which ANDs the line's direction bits out of +0xD) counts the overlap word (+0x20) down on every clear and, in its (-1, -1) form, clears the pair of the other axis' bits through 0x522730 (1 and 0x10 clear 4 and 0x40, 4 and 0x40 clear 1 and 0x10, by the link 0x522850), recursing on the extension cells (0xC, 0x11); OpenTPW removes the tile or counts the overlap down only, and the other writers of +0xD (the type-25 walk 0x52BA50 takes the first linked arm by rotation, the edit sub-modes 0x52B400) have no counterpart"),
		("TRACK-005", "TRACK-STATION: the station is the original's line of 0x52A1A0 from the attraction cell (the anchor): two tiles of type 13 or 18 on the footprint's rows 1 and 2 across the heading, the circuit starting at the first, the controller reference between the tiles (0x529E10, 0x545890) and the piece walks 0x52A490 and 0x52A700 starting where it does; the line ops of 0x53AAC0 are read: 0x80 writes the arms of a line (0x539220: each cell after the first gets the arm toward the previous cell and the previous cell the arm back, the first cell of a line none, because the step of a line's first cell is zeroed at the tool's start), 0x82 the flow link (0x539670), 0x83 the origin word of the tile and its three type 12 extension cells; approximated: the placement (0x524960 mode 4, 0x525254..0x525690) also lays a type 11 or 16 track tile at the exit cell and at the entry cell with the arm toward the station (0x87, the type op, 0x80, 0x82, 0x83 on each, the tool's first vertex at the exit), where OpenTPW writes both station tiles with both arms at once and lays the exit and entry tiles with the first and the last line, so the arms the exit and entry tiles hold before the circuit closes, the first line's start on an existing tile and what the placement charges for those two tiles are not reproduced"),
		("TRACK-007", "TRACK-DEMOLISH: removing a kart or water ride refunds the track cell cost x the ride's scrap percentage / 100 per tile its two replays clear (ClearCell 0x53B280 credits it at 0x53B622 for a cleared type 11 or 16 tile; the replays run with flag 0x81B46C = 1, so no end tile is skipped) and then charges 2 x the cell cost x the scrap percentage / 100 once (0x4D01F0, 0x528157..0x528179), both only for a type with Info.HasQueue (def+0x40) as the original; the replays are the original's: the chain from the station's exit to the open end of the track (0x530830, which also resets the pass counters, 1 at a corner or junction and else 0) and the chain from the tile before the station (0x530B70), so a tile no chain reaches stays in the park and refunds nothing, and a junction a chain passes loses one pass only (TrackEditor.Demolish); approximated: the original replays each line between two corner points through the click handler's mode 0x35, whose per-tile arm writes for the line's step ((0x53B280 with (+-2, 0) or (0, +-2): the arm the line used goes, the other stays while a pass remains) are modelled as one clear per tile in chain order, where a two-line full crossing whose laid flow includes the chain's heading takes the line step's rule (with two or more link bits 0x53B280 clears the link bit opposite to the step and both arms of the step's axis; 0x52FE50 replays each line from the later corner point back to the earlier one, so that bit is the chain's own heading) and any other junction keeps the cut's pass rule (0x53B280 with (-1, -1)) for its arms and link"),
		("TRACK-010", "TRACK-BRIDGE: a kart or water tile with at most two arms and no corner (straights, single-arm ends, armless tiles, 0x538AA4..0x538B05) is a bridge when it replaced path cells; the original tests the map layer under the track (a path or queue under any of its four cells, kept there and re-tested when a path is laid later) and only type 25 tests map types 2, 7 and 30 (water, outside the park and the fixed walkway); OpenTPW's track replaces the paths, so it remembers them when the tile is laid, writes no type 25, and takes the ahead and behind neighbours of the second pass from the flow link (an end or armless tile without a link along it takes the positive axis), whose PC twin is not traced"),
		("TRACK-018", "TRACK-ANIM: the pieces' arm masks and their m clips play as the original triggers them (BUMP 17, the placement, line and edit walks), and the renderer draws texture-coordinate clips only, which is all the shipped pieces need (the Crypt Karts' bridge clips gk_trckH*m carry one texture-frame track on the one-frame slot 0 whose 20 keys all name frame 0, the bind the piece already has, and no member of the archive animates the flame slot); the track edit sub-modes 0xE and 0x13 of the ride window's track button are built (TrackEditor, TrackEditWriter: the pick test 0x539760, the cut 0x52B400 with the clears 0x53B280, the end re-links 0x53BC60 and the station repair 0x52FC80, the walk 0x526BD0 that starts or stops the pieces, and the line tool from the open end 0x530830); Backspace now replays the collected existing corners through directional clears (0x52FE50, mode 0x35), sharing the refund and add-on hooks with cuts, and qualifying valid line/edit walks reopen through the attraction guard (0x4DF290 -> 0x4DF390), without opening on restore; residuals: the shared tool keeps at most 1024 points rather than the collector's 1025, the station-layout and full original replay/restore equivalence remain unverified (TRACK-004/007 are still open), and the hover's marking of the cut's tiles (the ghost op 0x10F of 0x52B400) is drawn as plain blueprint cells (BLUEPRINT-003)"),
		("TRACK-026", "TRACK-HEADS: a kart's, boat's or bumper car's riders are drawn as head sprites at the head dummies (class 0x100000B1: numbers 1 and 2 in the karts, 1 to 5 in the wr_ring boats) through the ride-head renderer in the original's seat order (rider list order, 0x549C60, called by the vehicle creation 0x549DB0 for every family); 0x0044B410 is the PC twin of ADDHEAD (it marks the head record 0x14 bytes apart and has 0x00475A10 create the head thing, type 1 or 3 for a costume head; its callers are the seat code 0x549C60, 0x43B600, 0x548E80, 0x557D80 and 0x55D830), whose sprite the shared thing renderer draws (the sizes belong to the HEADS entries); the boarding guest between BUMP 1 and the car's creation is not traced"),
		("TRACK-032", "SAVED-RIDE CONTROLLER: a saved kart or water ride's controller is rebuilt after a fresh re-walk. Native loader 0x543560 instead reads chunk 3's 40-byte field payload (0xd0 is the in-memory ride stride), reconstructs a distinct 0x1c waypoint chain from ride and chunk 4 tile parameters, restores chunk 5's raw 0xac controller records with relocation keys, and chunk 6 selects the reference waypoint: first flag 4, then mandatory advance with wrap and flag 2 skipping. SaveTrackRideBlock only reads structural chunks; waypoint reconstruction, runtime restoration and saved-versus-fresh verdict semantics remain unimplemented"),
	};
}
